def getHappyString(n: int, k: int) -> str:
    def backtrack(path):
        if len(path) == n:
            happy_strings.append(''.join(path))
            return
        for char in 'abc':
            if not path or char != path[-1]:
                path.append(char)
                backtrack(path)
                path.pop()

    happy_strings = []
    backtrack([])

    if k <= len(happy_strings):
        return happy_strings[k - 1]
    else:
        return ""
